let settings;try{settings=JSON.parse(localStorage.getItem('afterglow')||'{}')}catch{settings={}}
const frequencies=[31,62,125,250,500,1000,2000,4000,8000,16000],presets={Flat:Array(10).fill(0),'Bass boost':[6,5,4,2,0,0,0,0,0,0],Warm:[3,3,2,1,0,-1,-2,-2,-1,0],Vocal:[-3,-2,-1,1,3,4,3,1,0,-1],Electronic:[4,3,0,-2,-1,1,0,2,3,4]};
