$$('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));
function graph(){if(ctx)return;ctx=new AudioContext();source=ctx.createMediaElementSource(audio);pre=ctx.createGain();filters=frequencies.map(f=>{let n=ctx.createBiquadFilter();n.type='peaking';n.frequency.value=f;n.Q.value=1.2;return n});pan=ctx.createStereoPanner();compressor=ctx.createDynamicsCompressor();analyser=ctx.createAnalyser();analyser.fftSize=2048;let chain=[source,pre,...filters,pan,compressor,analyser,ctx.destination];chain.slice(0,-1).forEach((n,i)=>n.connect(chain[i+1]));applyEQ()}
