$('#preamp').value=settings.preamp??-6;$('#balance').value=settings.balance??0;
function levels(){settings.preamp=+$('#preamp').value;settings.balance=+$('#balance').value;$('#preampVal').textContent=settings.preamp+' dB';$('#balanceVal').textContent=settings.balance===0?'Center':Math.round(Math.abs(settings.balance)*100)+'% '+(settings.balance<0?'L':'R');applyEQ();persist()}
