const themes=[['Afterglow','#a9ef75','#101311','Soft green. Late-night energy.'],['Spotify','#1ed760','#121212','The familiar green room.'],['Cyberpunk','#f5e642','#100e20','Neon nights. Electric dreams.'],['Arctic','#80d7ef','#101d26','Cool tones. Clear head.']];
function setTheme(name,custom){let t=themes.find(t=>t[0]===name)||themes[0];document.documentElement.style.setProperty('--accent',custom||t[1]);document.documentElement.style.setProperty('--bg',t[2]);document.documentElement.style.setProperty('--panel',name==='Cyberpunk'?'#211b36':'#1b2424');settings.theme=t[0];settings.accent=custom||t[1];$('#accent').value=settings.accent;$$('.theme-card .check').forEach((e,i)=>e.textContent=themes[i][0]===t[0]?'✓':'');persist()}
themes.forEach(([name,color,bg,description])=>{let b=document.createElement('button');b.className='theme-card';b.innerHTML='<span class="swatch"></span><span><strong></strong><small></small></span><span class="check"></span>';b.querySelector('.swatch').style.background=`linear-gradient(135deg,${bg},${color})`;b.querySelector('strong').textContent=name;b.querySelector('small').textContent=description;b.onclick=()=>setTheme(name);$('#themeCards').append(b)});setTheme(settings.theme,settings.accent);$('#accent').oninput=e=>setTheme(settings.theme,e.target.value);
function demo(){let rate=22050,length=rate*40,buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer),str=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+length*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*2,true);for(let i=0;i<length;i++){let t=i/rate,beat=t%.5,notes=[130.81,155.56,196,233.08],f=notes[Math.floor(t/4)%4],fade=Math.min(t/2,(40-t)/3,1),s=(Math.sin(2*Math.PI*f*t)*.13+Math.sin(2*Math.PI*f*1.5*t)*.08+Math.sin(2*Math.PI*f*2*t)*.06)*(0.65+.35*Math.sin(t*1.7));s+=Math.sin(2*Math.PI*(50*beat+4*(1-Math.exp(-beat*35))))*Math.exp(-beat*14)*.25;v.setInt16(44+i*2,Math.max(-1,Math.min(1,s*fade))*32767,true)}return URL.createObjectURL(new Blob([buffer],{type:'audio/wav'}))}
function renderQueue(){let box=$('#queue');box.replaceChildren();tracks.forEach((t,i)=>{let row=document.createElement('div');row.className='track-row';let art=document.createElement('div');art.className='art';art.textContent=i===active?'♫':String(i+1).padStart(2,'0');let info=document.createElement('div');info.className='info';let title=document.createElement('strong');title.textContent=t.title;let sub=document.createElement('small');sub.textContent=t.artist||'YouTube · title to match';info.append(title,sub);let b=document.createElement('button');b.textContent='▶';b.setAttribute('aria-label','Play '+t.title);b.onclick=()=>playTrack(i);row.append(art,info,b);box.append(row)});$('#count').textContent=tracks.length+' tracks'}
function playbackState(playing){$('#play').textContent=playing?'Ⅱ':'▶';$('#heroPlay').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause':'Play')}
async function playTrack(i){active=i;let t=tracks[i];audio.pause();if(ytReady)yt.pauseVideo();try{if(t.type==='query'){notify('Finding a match on YouTube…');let result=await searchYT(t.title+' '+(t.artist||''),1);if(!result.length)throw Error('No playable match found. Try a different title.');t.video=result[0].id.videoId;t.type='youtube'}if(t.type==='youtube'){currentType='youtube';page('search');$('#youtubeWrap').hidden=false;loadYouTube(t.video)}else{currentType='local';graph();await ctx.resume();if(!t.url)t.url=demo();audio.src=t.url;await audio.play()}$('#trackTitle').textContent=t.title;$('#trackArtist').textContent=t.artist||'YouTube';$('#heroTitle').textContent=t.title;$('#heroSub').textContent=t.artist||'YouTube';$('#sourceLabel').textContent=t.type==='youtube'?'YOUTUBE · AMBIENT VISUALS':'LOCAL AUDIO · REACTIVE VISUALS';renderQueue();if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist||'YouTube'});navigator.mediaSession.setActionHandler('play',toggle);navigator.mediaSession.setActionHandler('pause',toggle);navigator.mediaSession.setActionHandler('nexttrack',()=>next(1));navigator.mediaSession.setActionHandler('previoustrack',()=>next(-1))}}catch(e){notify(e.message);playbackState(false)}}
async function toggle(){if(currentType==='youtube'&&ytReady){yt.getPlayerState()===1?yt.pauseVideo():yt.playVideo();return}if(!audio.src)return playTrack(active);try{graph();await ctx.resume();if(audio.paused)await audio.play();else audio.pause()}catch(e){notify('Playback failed: '+e.message)}}
