const time=n=>Number.isFinite(n)?Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0'):'0:00';setInterval(()=>{let d=currentType==='youtube'&&ytReady?yt.getDuration():audio.duration,t=currentType==='youtube'&&ytReady?yt.getCurrentTime():audio.currentTime;$('#duration').textContent=time(d);$('#elapsed').textContent=time(t);$('#seek').value=d?t/d*100:0},500);$('#seek').oninput=e=>{let fraction=e.target.value/100;if(currentType==='youtube'&&ytReady)yt.seekTo(yt.getDuration()*fraction,true);else if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*fraction};
$('#addLocal').onclick=$('#localTile').onclick=()=>$('#localFiles').click();$('#listTile').onclick=()=>$('#listFile').click();$('#localFiles').onchange=e=>{let start=tracks.length;for(let f of e.target.files){tracks.push({title:f.name.replace(/\.[^.]+$/,''),artist:'Local file · '+(f.size/1048576).toFixed(1)+' MB',type:'local',url:URL.createObjectURL(f)})}renderQueue();if(tracks.length>start){notify((tracks.length-start)+' tracks added');playTrack(start)}e.target.value=''};
function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field.trim());field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('CSV contains an unclosed quote.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows}
$('#listFile').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>1048576)throw Error('Please use a playlist smaller than 1 MB.');let text=(await f.text()).replace(/^\uFEFF/,''),rows=f.name.toLowerCase().endsWith('.csv')?parseCSV(text):text.split(/\r?\n/).filter(x=>x.trim()).map(x=>[x.trim()]);let header=rows[0]?.map(x=>x.toLowerCase()),titleIndex=header?.findIndex(x=>['title','song','track','song title'].includes(x))??-1,artistIndex=header?.indexOf('artist')??-1;if(titleIndex>=0)rows.shift();let added=0;for(let r of rows.slice(0,500)){let title=r[titleIndex>=0?titleIndex:0];if(title){let video=videoId(title);tracks.push({title,artist:artistIndex>=0?r[artistIndex]:'',type:video?'youtube':'query',video});added++}}renderQueue();notify(added+' titles imported'+(!apiKey?' · Connect YouTube in Settings to match titles.':''))}catch(err){notify(err.message)}e.target.value=''};
