async function searchYT(q,max=10){if(!apiKey)throw Error('Connect a YouTube API key in Settings, or paste a YouTube link.');let url=new URL('https://www.googleapis.com/youtube/v3/search');url.search=new URLSearchParams({part:'snippet',type:'video',videoEmbeddable:'true',q,maxResults:max,key:apiKey});let res=await fetch(url);let data=await res.json();if(!res.ok)throw Error(data.error?.message||'YouTube search unavailable');return data.items||[]}
$('#searchForm').onsubmit=async e=>{e.preventDefault();let q=$('#query').value.trim(),id=videoId(q),box=$('#results');box.textContent='Searching…';try{if(id){tracks.push({title:'YouTube track',artist:'YouTube',type:'youtube',video:id});box.textContent='Added to your queue.';await playTrack(tracks.length-1);return}let items=await searchYT(q);box.replaceChildren();if(!items.length)box.textContent='No matches. Try another song or artist.';for(let item of items){let row=document.createElement('div');row.className='track-row';let info=document.createElement('div');info.className='info';let title=document.createElement('strong');let decode=document.createElement('textarea');decode.innerHTML=item.snippet.title;title.textContent=decode.value;let sub=document.createElement('small');sub.textContent=item.snippet.channelTitle;info.append(title,sub);let b=document.createElement('button');b.textContent='▶';b.setAttribute('aria-label','Play '+title.textContent);b.onclick=()=>{tracks.push({title:title.textContent,artist:sub.textContent,type:'youtube',video:item.id.videoId});playTrack(tracks.length-1)};row.append(info,b);box.append(row)}}catch(err){box.textContent=err.message}};
