const canvas=$('#visual'),g=canvas.getContext('2d');let data=new Uint8Array(1024),wave=new Uint8Array(2048);function draw(t){requestAnimationFrame(draw);let w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==w*devicePixelRatio||canvas.height!==h*devicePixelRatio){canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio}g.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);g.fillStyle='#07100e';g.fillRect(0,0,w,h);let live=analyser&&!audio.paused&&currentType==='local';if(live)analyser.getByteFrequencyData(data);let energy=live?data.slice(0,100).reduce((a,b)=>a+b,0)/25500:0,accent=settings.accent||'#a9ef75';if(mode==='spectrum'){for(let i=0;i<48;i++){let v=live?data[i*3]/255:.12+.08*Math.sin(i*.5+t*.001);g.fillStyle=accent;g.globalAlpha=.3+i/70;g.fillRect(i*w/48+2,h*.7-v*h*.5,w/48-4,v*h*.5)}g.globalAlpha=1}else if(mode==='wave'){if(live)analyser.getByteTimeDomainData(wave);g.strokeStyle=accent;g.lineWidth=2;g.shadowColor=accent;g.shadowBlur=15;g.beginPath();for(let x=0;x<w;x++){let y=h*.45+(live?(wave[Math.floor(x/w*2048)]-128)/128*h*.4:Math.sin(x*.025+t*.001)*20*Math.sin(x/w*Math.PI));x?g.lineTo(x,y):g.moveTo(x,y)}g.stroke();g.shadowBlur=0}else{g.save();g.translate(w*.5,h*.43);g.globalCompositeOperation='screen';for(let j=0;j<62;j++){g.beginPath();let radius=Math.min(w,h)*(.21+j*.0018)*(1+energy*.3);for(let i=0;i<=200;i++){let a=i/200*Math.PI*2,warp=Math.sin(a*3+t*.0004+j*.06)*18+Math.cos(a*5-t*.0003+j*.04)*10,r=radius+warp,x=Math.cos(a)*r*1.4,y=Math.sin(a)*r*.75; i?g.lineTo(x,y):g.moveTo(x,y)}g.strokeStyle=j<32?'#6debb3':'#9f81d6';g.globalAlpha=.035+.035*Math.sin(j/62*Math.PI);g.lineWidth=1.5;g.stroke()}g.restore();for(let i=0;i<45;i++){let x=(Math.sin(i*832)*.5+.5)*w,y=(Math.cos(i*327)*.5+.5)*h;g.fillStyle='#b7d2bc';g.globalAlpha=.15+.18*Math.sin(t*.0005+i);g.fillRect(x,y,1,1)}g.globalAlpha=1}let shade=g.createLinearGradient(0,h*.45,0,h);shade.addColorStop(0,'#07100e00');shade.addColorStop(1,'#07100ef0');g.fillStyle=shade;g.fillRect(0,0,w,h)}